using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SandstormCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/SandstormCustomDescription", order = 0)]
public class SandstormCustomDescription : WhereXTimesCustomDescription
{
	[SerializeField]
	private MinimumSoulHeatBasedAction minimumSoulHeatBasedAction;

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		SandstormAction sandstormAction = battleAction as SandstormAction;
		string actionDescription = GetActionDescription(amountModified, battleAction, sandstormAction.PurifyAction);
		string text = (sandstormAction.ResetSoulHeat ? ("\n" + base.localizationManager.GetLocalizedResetSoulHeat()) : "");
		return actionDescription + text;
	}
}
